add_filter( 'woocommerce_account_downloads_columns', 'perfectpixel_rename_downloads_columns', 30 );

function perfectpixel_rename_downloads_columns( $columns ) {
	foreach ( explode( '|', '{{download_column_titles}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && isset( $columns[ $parts[0] ] ) && '' !== $parts[1] ) {
			$columns[ $parts[0] ] = $parts[1];
		}
	}
	return $columns;
}
